package com.bank.stream.model;

// A transaction carrying both its real event minute and its arrival minute.
public class TimedTxn {
    private final String accountId;
    private final int eventMinute;        // when it actually happened at the branch
    private final int processingMinute;   // when Spark saw it

    public TimedTxn(String accountId, int eventMinute, int processingMinute) {
        this.accountId = accountId;
        this.eventMinute = eventMinute;
        this.processingMinute = processingMinute;
    }

    public String getAccountId() { return accountId; }
    public int getEventMinute() { return eventMinute; }
    public int getProcessingMinute() { return processingMinute; }
}
