package com.bank.stream.service;

import com.bank.stream.model.TimedTxn;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

// Buckets transactions by a chosen clock, applying a watermark for event time.
public class WindowBucketer {

    // Count per minute using event time, dropping events older than the watermark.
    public Map<Integer, Long> byEventTime(List<TimedTxn> txns, int watermarkDelay) {
        int maxEvent = txns.stream().mapToInt(TimedTxn::getEventMinute).max().orElse(0);
        int watermark = maxEvent - watermarkDelay; // boundary below which events are too late
        Map<Integer, Long> counts = new TreeMap<>();
        for (TimedTxn t : txns) {
            if (t.getEventMinute() < watermark) continue; // too late → dropped
            counts.merge(t.getEventMinute(), 1L, Long::sum);
        }
        return counts;
    }

    // Count per minute using processing time (wrong for delayed events).
    public Map<Integer, Long> byProcessingTime(List<TimedTxn> txns) {
        Map<Integer, Long> counts = new TreeMap<>();
        for (TimedTxn t : txns) {
            counts.merge(t.getProcessingMinute(), 1L, Long::sum);
        }
        return counts;
    }
}
