package com.bank.stream;

import com.bank.stream.model.TimedTxn;
import com.bank.stream.service.WindowBucketer;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: compare event-time vs processing-time bucketing.
public class EventTimeDemo {

    private static final Logger log = Logger.getLogger(EventTimeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        WindowBucketer bucketer = new WindowBucketer();

        // SAV2001 happened at minute 59 but arrived at minute 60 (delayed).
        // CUR3001 happened and arrived at minute 60.
        // An ancient event at minute 40 is far behind the watermark.
        List<TimedTxn> txns = List.of(
            new TimedTxn("SAV2001", 59, 60),
            new TimedTxn("CUR3001", 60, 60),
            new TimedTxn("SAV2001", 60, 60),
            new TimedTxn("OLD0001", 40, 60));

        var byEvent = bucketer.byEventTime(txns, 10);     // watermark = 60 - 10 = 50
        var byProc = bucketer.byProcessingTime(txns);

        log.info(() -> "Event-time minute counts (correct):     " + byEvent);
        log.info(() -> "Processing-time minute counts (wrong):  " + byProc);
        log.info("Event-time vs processing-time comparison complete.");
    }
}
